shell_commands.command:
cd /testbed && python3 - <<'PY'
from pathlib import Path
p = Path('lucene/core/src/test/org/apache/lucene/geo/TestGeoEncodingUtils.java')
s = p.read_text()
needle = '  // check edge/interesting cases explicitly\n'
addition = '''  public void testComponentPredicateCloseToNorthPole() {
    double minLat = decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = decodeLatitude(Integer.MAX_VALUE);
    double minLon = decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = decodeLongitude(Integer.MAX_VALUE);
    Polygon polygon =
        new Polygon(
            new double[] {minLat, minLat, maxLat, maxLat, minLat},
            new double[] {minLon, maxLon, maxLon, minLon, minLon});
    GeoEncodingUtils.Component2DPredicate predicate =
        GeoEncodingUtils.createComponentPredicate(LatLonGeometry.create(polygon));

    assertTrue(predicate.test(Integer.MAX_VALUE - 2, Integer.MAX_VALUE - 2));
    assertTrue(predicate.test(Integer.MAX_VALUE, Integer.MAX_VALUE));
    assertFalse(predicate.test(Integer.MAX_VALUE - 4, Integer.MAX_VALUE - 2));
    assertFalse(predicate.test(Integer.MAX_VALUE - 2, Integer.MAX_VALUE - 4));
    assertFalse(predicate.test(Integer.MIN_VALUE, Integer.MAX_VALUE - 2));
  }

  public void testDistancePredicateCloseToNorthPole() {
    double lat = decodeLatitude(Integer.MAX_VALUE - 2);
    double lon = decodeLongitude(Integer.MAX_VALUE - 2);
    GeoEncodingUtils.DistancePredicate predicate =
        GeoEncodingUtils.createDistancePredicate(lat, lon, 0.01);

    assertTrue(predicate.test(Integer.MAX_VALUE - 2, Integer.MAX_VALUE - 2));
    assertFalse(predicate.test(Integer.MAX_VALUE - 64, Integer.MAX_VALUE - 2));
    assertFalse(predicate.test(Integer.MIN_VALUE, Integer.MAX_VALUE - 2));
  }

'''
assert s.count(needle) == 1
p.write_text(s.replace(needle, addition + needle))
p = Path('lucene/test-framework/src/java/org/apache/lucene/tests/geo/BaseGeoPointTestCase.java')
s = p.read_text()
s = s.replace('import org.apache.lucene.geo.Component2D;\n', 'import org.apache.lucene.geo.Component2D;\nimport org.apache.lucene.geo.GeoEncodingUtils;\n')
needle = '  /** test we can search for a polygon with a hole (but still includes the doc) */\n'
addition = '''  public void testNarrowPolygonCloseToNorthPole() throws Exception {
    double minLat = GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE - 3);
    double maxLat = GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE);
    double minLon = GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE - 3);
    double maxLon = GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE);
    try (Directory dir = newDirectory();
        RandomIndexWriter writer = new RandomIndexWriter(random(), dir)) {
      Document doc = new Document();
      addPointToDoc(
          FIELD_NAME,
          doc,
          GeoEncodingUtils.decodeLatitude(Integer.MAX_VALUE - 2),
          GeoEncodingUtils.decodeLongitude(Integer.MAX_VALUE - 2));
      writer.addDocument(doc);

      try (IndexReader reader = writer.getReader()) {
        IndexSearcher searcher = newSearcher(reader);
        Query query =
            newPolygonQuery(
                FIELD_NAME,
                new Polygon(
                    new double[] {minLat, minLat, maxLat, maxLat, minLat},
                    new double[] {minLon, maxLon, maxLon, minLon, minLon}));
        assertEquals(1, searcher.count(query));
      }
    }
  }

'''
assert s.count(needle) == 1
p.write_text(s.replace(needle, addition + needle))
PY
./gradlew :lucene:core:test --offline --tests 'org.apache.lucene.geo.TestGeoEncodingUtils.test*CloseToNorthPole' --tests 'org.apache.lucene.search.TestLatLon*Queries.testNarrowPolygonCloseToNorthPole' --console=plain > /tmp/lucene-polar-regression.log 2>&1; result=$?; tail -100 /tmp/lucene-polar-regression.log; exit "$result"

